insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_udayagiri_caves','Udayagiri & Khandagiri Caves','Odisha','Khordha','Heritage','Carved into twin hills facing each other, Udayagiri (18 caves) and Khandagiri (15 caves) served as residential blocks for Jain monks during the reign of King Kharavela of the Mahameghavahana dynasty. Features the celebrated 17-line Brahmi script Hathigumpha inscription.','20.2631','85.7864','needs_review','October – March','1',array['archaeology','caves','heritage','jainism','history','viewpoint','day trip']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
