insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_barunei','Barunei Hill & Temple','Odisha','Khordha','Mountain','Barunei Hill served as the last stronghold of the independent kings of Khordha and the cradle of the historic Paika Rebellion (1817) against British rule. The hill features shrines of Goddess Barunei and Karunei, a perennial spring called Swarna Ganga, and lush forest walking trails.','20.1583','85.6417','needs_review','July – February','1',array['hill','waterfall','history','paika rebellion','temple','day trip','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_atri','Atri Sulphur Hot Springs & Hattakeswar Temple','Odisha','Khordha','Nature','Atri is famous for its natural hot spring enriched with medicinal sulphur content, maintaining a constant temperature of 57°C (135°F). Visitors take holy dips in dedicated bathing complexes believed to cure skin diseases. Nearby stands Lord Hattakeswar Shiva Temple.','20.15','85.5167','needs_review','October – March','1',array['hot spring','spiritual','wellness','nature','day trip','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_deras_jhumka','Jhumka & Deras Twin Dam Escapes','Odisha','Khordha','Lake','Jhumka and Deras are twin dams constructed over hill streams inside Chandaka forest perimeter. Surrounded by dense reserve forest, the quiet blue waters and earth embankments offer scenic sunset and sunrise panoramas popular with cyclists, photographers, and weekend picnickers.','20.3417','85.7','needs_review','September – March','1',array['dam','lake','picnic','nature','peaceful','road trip','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ekamra_kanan','Ekamra Kanan Botanical Garden & Lake','Odisha','Khordha','Nature','Ekamra Kanan (Regional Plant Resource Centre) is the largest botanical garden in Bhubaneswar. Spanning 500 acres, it features a vast lake with paddle boating, Asia''s largest cactus house collection (over 1,050 species), a vibrant rose garden, and sprawling lawns.','20.3083','85.8167','needs_review','November – February','1',array['park','botanical garden','lake','boating','city escape','low cost escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_shikharachandi','Shikharachandi Hill Temple & Park','Odisha','Khordha','Mountain','Perched on a rocky hillock in Patia, Shikharachandi Temple is a beloved local sunset point. Recent eco-park developments have added landscaped steps, walkways, lighting, and viewing decks offering 360-degree views of Bhubaneswar''s tech corridor and northern hills.','20.3528','85.8167','needs_review','Year-round (Best evenings)','1',array['hill','viewpoint','temple','sunset spot','low cost escape','city escape']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_puri_beach','Puri Beach & Swargadwar','Odisha','Puri','Beach','Puri Beach is famous worldwide for its long stretch of fine golden sand and high roaring waves of the Bay of Bengal. Home to Padma Shri Sudarsan Pattnaik''s sand art displays, the beach features dedicated Blue Flag certified clean zone (Golden Beach), traditional Nolias (lifeguards), and evening beach bazaars.','19.7983','85.8249','needs_review','October – March','2',array['beach','golden sand','bay of bengal','sea','sunrise','weekend']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
