insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chilika_satapada','Chilika Lake — Satapada Dolphin Sanctuary','Odisha','Puri','Wildlife','Satapada (''Seven Villages'') sits on the mouth of Chilika Lake where the lagoon opens into the ocean. Famous as the natural habitat of endangered Irrawaddy Dolphins (Orcaella brevirostris), boat safaris take visitors to spot dolphins surfacing, visit Sea Mouth island, and Rajhans island beach.','19.6739','85.4264','needs_review','November – February','1',array['chilika','dolphins','irrawaddy','lake','boat safari','sea mouth','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
