insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_barabati','Barabati Fort & Stadium Cuttack','Odisha','Cuttack','Heritage','Built by Ganga ruler King Anangabhima Deva III in the 14th century, Barabati Fort sits on the delta tongue between Mahanadi and Kathajodi rivers. Though mostly ruined during British rule, the fort retains its carved stone gateway, moat, and 9-tiered palace mound (Navatala Prasada). Home to Cuttack Chandi shrine and Barabati Stadium.','20.4819','85.8672','needs_review','October – March','1',array['fort','heritage','history','moat','city escape','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
