insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_dhabaleswar','Dhabaleswar Island & Hanging Bridge','Odisha','Cuttack','Island','Dhabaleswar is a lush river island situated in the middle of the Mahanadi River. Dedicated to Lord Shiva (Dhabaleswar), the island is accessed via a 254-meter long pedestrian suspension hanging bridge or traditional ferry boats from the river bank. Famous for its Bada Osha festival.','20.5167','85.8333','needs_review','October – March','1',array['island','temple','hanging bridge','river','spiritual','day trip','low cost escape']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
