insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_duduma','Duduma Waterfall & Machkund Gorge','Odisha','Koraput','Waterfall','Duduma Waterfall is a magnificent 175-meter (574 feet) plunge formed by the Machkund River as it drops into a dramatic forest canyon on the Odisha-Andhra border. The surrounding Onukudelli area is famous for the Thursday weekly market of the primitive Bonda and Gadaba tribes.','18.5167','82.5333','needs_review','September – March','1',array['waterfall','gorge','machkund','tribal','bonda tribe','nature']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
