insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_daringbadi','Daringbadi — ''Kashmir of Odisha''','Odisha','Kandhamal','Mountain','Situated at 915 meters (3,000 feet) in Kandhamal district, Daringbadi is affectionately dubbed the ''Kashmir of Odisha''. It is the only place in Odisha where winter temperatures occasionally drop to 0°C with morning frost on pine needles. Features pine forests, black pepper & coffee gardens, Lovers Point, Midubanda Falls, and Nature Park.','19.9167','83.9167','needs_review','September – March (Dec/Jan for winter frost)','2',array['hill station','kashmir of odisha','pine forest','coffee garden','waterfall','sub-zero winter','weekend']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
