insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sanaghagara','Sanaghagara & Badaghagara Waterfalls','Odisha','Keonjhar','Waterfall','Sanaghagara (''Small Waterfall'') and Badaghagara (''Big Waterfall'') are twin perennial waterfalls situated 5 km and 9 km respectively from Keonjhar town. Sanaghagara features a 30-foot drop into a clear pool set inside a landscaped eco-park with gardens and walkways.','21.6167','85.55','needs_review','September – March','1',array['waterfall','nature park','picnic','family','hills','day trip']::text[],true,'needs_review') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_chandipur','Chandipur Receding Beach','Odisha','Balasore','Beach','Chandipur-on-Sea is world-famous for its ''Hide and Seek'' beach phenomenon. Due to unique seabed geography, the ocean recedes up to 5 kilometers (3 miles) away from the shore twice every day during low tide, allowing visitors to literally walk or ride bicycles on the exposed sea bed.','21.47','87.02','needs_review','October – March','1',array['beach','receding sea','unique phenomenon','horseshoe crab','nature','must see']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
