insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_mahendragiri','Mahendragiri Peak (1501m) & Ancient Temples','Odisha','Gajapati','Mountain','Mahendragiri is Odisha''s second highest peak (1,501 meters), steeped in Vedic and Ramayana legends as the abode of Sage Parashurama. Located in Eastern Ghats near Andhra border, the mist-clad summit holds 5th-century Gupta-era stone temples named after the Pandavas (Kunti, Yudhishthira, Bhima). Known for rich medicinal flora.','18.9667','84.3667','needs_review','October – March (Shivratri trek in Feb/Mar)','2',array['mountain','trekking','ramayana','pandava temples','eastern ghats','offbeat','biodiversity']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
