insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sarankul_ladubaba','Sarankul Ladubaba Temple','Odisha','Nayagarh','Temple','Ladubaba Temple at Sarankul is one of Central Odisha''s prime Shiva shrines, dating back to the 15th century. Blending Shaivite and Vaishnavite rituals (Harihara worship), the presiding lingam is worshipped with both bilva leaves and tulsi. Massive crowds gather during Mahashivaratri for the lighting of the Mahadipa.','20.0883','85.1286','needs_review','October – March','1',array['shiva','harihara','temple','spiritual','healing','pilgrimage']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
