insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_ranipur_jharial','Ranipur-Jharial 64 Yogini Complex','Odisha','Balangir','Heritage','Ranipur-Jharial is acclaimed as the ''Soma Tirtha'' of ancient scriptures. Spanning a massive sandstone outcrop, the site features one of India''s only four surviving circular hypaethral (roofless) 64 Yogini temples. In addition to the Yogini circle, the site preserves over 50 monuments spanning Shaivite, Vaishnavite, Buddhist, and Tantric heritage.','20.2833','82.9667','needs_review','October – February','1',array['64 yogini','tantra','9th century','hypaethral','somavamsi','heritage','rock outcrop']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
