insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_khiching','Kichakeswari Black Chlorite Temple','Odisha','Mayurbhanj','Heritage','Khiching was the ancient capital of the Bhanja rulers from the 8th to 12th centuries AD. The crowning jewel is the Maa Kichakeswari Temple, constructed entirely of lustrous black chlorite stone with museum-grade sculptures. The adjacent archaeological museum houses life-size statues of Buddhist, Shaivite, and Jain deities.','21.9167','85.8333','needs_review','October – March','1',array['black chlorite','bhanja dynasty','10th century','temple','museum','archaeology']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
