insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_kolab_reservoir','Upper Kolab Dam & Botanical Gardens','Odisha','Koraput','Lake','Located at an altitude of 3,000 feet above sea level, Upper Kolab Dam generates hydro-electricity while creating a majestic reservoir. Adjoining the dam crest, a tiered botanical garden with colorful terraces, fountains, and boating lagoons offers cool mountain breezes year-round.','18.7833','82.6167','needs_review','September – March','1',array['reservoir','botanical garden','lake','hills','cool breeze','boating']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
