insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_sitabinji_paintings','Sitabinji Fresco Painting & Ravana Chhaya','Odisha','Keonjhar','Heritage','Sitabinji is one of the rarest ancient pictorial sites in India. Sheltered under a natural rock overhang called Ravana Chhaya, the site preserves a 5th-century AD tempera fresco painting depicting Maharaja Disabhanja leading a royal procession mounted on an elephant with cavalry and foot soldiers.','21.5167','85.7667','needs_review','October – March','1',array['fresco painting','gupta era','5th century','ravana chhaya','ancient art','rock shelter']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
