insert into public.avara_destinations(id,name,region,district,category,description,latitude,longitude,coordinate_status,season_note,suggested_days,tags,published,review_status) values ('od_tikarpada_gorge_camp','Tikarpada Gharial Sanctuary & Satkosia Gorge','Odisha','Angul','Wildlife','At Tikarpada, the mighty river Mahanadi carves a breathtaking 22-km deep gorge through the Eastern Ghats known as Satkosia. Home to the world-renowned Gharial and Mugger crocodile research and breeding center, visitors stay in luxury white-sand riverbed tents and embark on canyon boat safaris.','20.6','84.85','needs_review','November – March','2',array['gharial','satkosia gorge','mahanadi river','river rafting','eco-tents','crocodiles']::text[],true,'source_linked') on conflict(id) do update set name=excluded.name,region=excluded.region,district=excluded.district,category=excluded.category,description=excluded.description,latitude=excluded.latitude,longitude=excluded.longitude,season_note=excluded.season_note,tags=excluded.tags,coordinate_status=excluded.coordinate_status,suggested_days=excluded.suggested_days,review_status=excluded.review_status;
